// Accept either host, same path
const wantedResources = [
  "/users/austrump@arcsage.com.au/mailFolders('inbox')/messages"
];

// Allow multiple acceptable URLs
const ALLOWED_URLS = [
  "https://n8n.arcsage.com.au/webhook/ms-mail-incoming",
  "https://mailhook.arcsage.com.au/webhook/ms-mail-incoming"
];

// Helpers
const normUrl = (u) => {
  if (!u) return "";
  try {
    const url = new URL(u);
    const host = url.host.toLowerCase();
    let path = url.pathname;
    if (path.length > 1 && path.endsWith("/")) path = path.slice(0, -1);
    return `${url.protocol}//${host}${path}`;
  } catch {
    return (u || "").trim().toLowerCase();
  }
};

const ALLOWED = new Set(ALLOWED_URLS.map(normUrl));
const isAllowedUrl = (u) => ALLOWED.has(normUrl(u));

// Main
const now = new Date();

// Graph HTTP node usually gives { value: [...] }
const all = $json.value || [];

// Keep only our resource and allowed URL
const mine = all.filter(s =>
  wantedResources.includes(s?.resource) &&
  isAllowedUrl(s?.notificationUrl)
);

// Parse expiry once
const withExp = mine.map(s => ({
  ...s,
  _exp: new Date(s.expirationDateTime)
}));

// Partition by time
const active  = withExp.filter(s => s._exp > now);
const expired = withExp.filter(s => s._exp <= now);

// Choose a single keeper among active subs, latest expiry wins
active.sort((a, b) => b._exp - a._exp);
const keep = active[0] || null;

// Only other active subs are duplicates to delete
const duplicates = keep
  ? active.filter(s => s.id !== keep.id)
  : [];

// Return summary for next nodes
return [{
  json: {
    keepId: keep?.id || null,
    keepExp: keep?.expirationDateTime || null,
    counts: {
      mine: mine.length,
      active: active.length,
      expired: expired.length
    },
    duplicates
  }
}];

