// Compose F1 — build F1 follow-up email payload

function toStr(x) {
  const s = (x ?? '').toString();
  return /^(undefined|null)$/i.test(s.trim()) ? '' : s;
}

function firstWord(s) {
  s = toStr(s).trim();
  return s ? s.split(/\s+/)[0] : '';
}

function stripHtml(h = '') {
  return toStr(h).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

function escapeHtml(s) {
  return toStr(s).replace(/[&<>"]/g, function (c) {
    const map = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      '\'': '&#39;',
    };
    return map[c] || c;
  });
}

function extractMsgFromDb(s) {
  let txt = toStr(s).replace(/\r/g, '');
  const m = txt.match(/(?:Message:|Comments:)\s*([\s\S]*)$/i);
  if (!m) return '';
  return m[1].replace(/[ \t]+\n/g, '\n').trim();
}

function validEmail(s) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);
}

// 1) Pick recipient email
let email =
  toStr($json.email) ||
  toStr($json.lead_email) ||
  toStr($json.to) ||
  toStr($json.contact_email) ||
  toStr($json.Email) ||
  '';

email = email.trim().toLowerCase();

// 2) Also require client_id
const client_id = toStr($json.client_id).trim();

// Inputs for content
const given       = toStr($json.given_name);
const family      = toStr($json.family_name);
const displayName = toStr($json.display_name);
const origin_id   = toStr($json.origin_id);

// Logo
const logoUrl =
  toStr($json.logo_url) ||
  'https://raw.githubusercontent.com/winstonpgao/arcsage-assets/main/austrumplogo.jpeg';

// oneLine flag
const oneLine = (function () {
  const v = ($json.oneLine ?? $json.oneline ?? false);
  if (typeof v === 'boolean') return v;
  if (typeof v === 'number') return v === 1;
  const s = String(v).trim().toLowerCase();
  return s === 'true' || s === '1' || s === 'yes' || s === 'y';
})();

// Title extraction
let title = toStr($json.property_title).trim();
const subjIn = toStr($json.subject);
if (!title) {
  let m =
    subjIn.match(/Enquiry\s+for\s+(.+)$/i) ||
    subjIn.match(/\[([^\]]+)\]/) ||
    subjIn.match(/^([^–-]+)\s*[–-]\s*.*$/);
  if (m) title = toStr(m[1]).trim();
}
if (!title) title = 'the property';

// Message preview
let msg = toStr($json.lead_message);
if (!msg) {
  const source = toStr($json.body_plain) || stripHtml($json.body_html);
  msg = extractMsgFromDb(source);
}
if (msg.length > 300) msg = msg.slice(0, 300) + '…';

// Salutation
const first = given || firstWord(displayName) || (email.split('@')[0]) || 'there';
const salutation = family ? `${first} ${family}` : first;

// Subject and links
const subject = `Checking in about ${title}`;

const base = 'https://n8n.arcsage.com.au/webhook/toggle-sub-v3';
const unsubUrl = `${base}?a=unsub&e=${encodeURIComponent(email)}&t=${encodeURIComponent(client_id)}&src=F1`;
const resubUrl = `${base}?a=resub&e=${encodeURIComponent(email)}&t=${encodeURIComponent(client_id)}&src=F1`;

// Plain text body
const lines = [
  `Hi ${salutation},`,
  ``,
  `Just wanted to follow up regarding ${title} and see how things are going with your property search.`,
  ``,
  `If you’re still exploring, I can also help find a few similar options that might suit what you’re looking for.`,
  ``,
  `Happy to assist whenever it’s convenient for you.`,
  ``,
  ``,
];

if (msg) {
  lines.push(
    `Your previous enquiry message:`,
    `--------------------`,
    msg,
    `--------------------`,
    ``,
    ``
  );
} else {
  lines.push(``, ``);
}

lines.push(
  `Kind regards,`,
  `Austrump Glen Team`,
  ``,
  ``,
  `Stop these emails: ${unsubUrl}`,
  `Subscribe again (if you unsubscribed): ${resubUrl}`
);

const body = lines.join('\r\n');

// HTML body
const NBSP = '&nbsp;';
const spacer = function (h) {
  return `<div style="height:${h}px;line-height:${h}px;font-size:${h}px;mso-line-height-rule:exactly;">${NBSP}</div>`;
};
const oneLineGap = spacer(10);
const twoLines = spacer(10) + spacer(10);

const logoBlock = logoUrl
  ? `<div style="margin-top:0;">
       <img src="${escapeHtml(logoUrl)}" alt="Austrump Glen" width="140" style="width:140px;max-width:140px;height:auto;display:block;border:0;outline:none;text-decoration:none;">
     </div>`
  : ``;

const msgBox = msg
  ? `<div style="margin:8px 0 0 0;padding:10px 12px;border:1px solid #e0e0e0;border-radius:8px;background:#fafafa;white-space:pre-wrap;">${escapeHtml(msg)}</div>`
  : ``;

const gapBetweenSigAndLogo = oneLine ? oneLineGap : twoLines;

const body_html = `
<p style="margin:0 0 12px 0;">Hi ${escapeHtml(salutation)},</p>
${twoLines}

<p style="margin:0 0 12px 0;">
  Just wanted to follow up regarding <strong>${escapeHtml(title)}</strong> and see how things are going with your property search.
</p>

<p style="margin:0 0 12px 0;">
  If you’re still exploring, I can also help find a few similar options that might suit what you’re looking for.
</p>

<p style="margin:0 0 12px 0;">Happy to assist whenever it’s convenient for you.</p>

${twoLines}

<p style="margin:0;">Kind regards,<br>Austrump Glen Team</p>

${gapBetweenSigAndLogo}

${logoBlock}

${twoLines}
${twoLines}

${msg ? `<p style="margin:0 0 6px 0;"><em>Your previous enquiry message:</em></p>${msgBox}` : ``}

${twoLines}

<p style="margin:0;font-size:12px;color:#666">
  Stop these emails: <a href="${unsubUrl}">Unsubscribe</a><br>
  Changed your mind? <a href="${resubUrl}">Subscribe again</a>
</p>
`.trim();

// Build output JSON
const out = {
  template: 'F1',
  mailbox: 'austrump@arcsage.com.au',
  subject,
  body,
  body_html,
  client_id,
  origin_enquiry_id: origin_id,
  unsubUrl,
  resubUrl,
  _oneLine: oneLine
};

// Only set "to" if valid; otherwise mark skip_send=true
if (validEmail(email) && client_id) {
  out.to = email;
  out.skip_send = false;
} else {
  out.skip_send = true;
  out.skip_reason = `invalid recipient or missing client_id (email='${email}', client_id='${client_id}')`;
}

// Function node must return one object with a json key
return {
  json: out,
};

// Extract Lead (EML path) — robust version (drop-in for a Code node)

// --- helpers ---
function toStr(x){ const s=(x??'').toString().trim(); return (!s||/^(undefined|null)$/i.test(s))?'':s; }
function t(x){ return toStr(x).replace(/\s+/g,' '); }
function strip(h=''){ return toStr(h).replace(/<[^>]+>/g,' '); }

// prefer HTML, fallback to plain
const html  = $json.html  || $json.body_html  || '';
const plain = $json.plain || $json.body_plain || '';
const src   = html && html.length ? html : plain;

// allow multiple tags between label and value
const TAGS = '(?:<\\/?[^>]*>\\s*)*';

// --- email ---
let lead_email = '';
{
  let m = src.match(new RegExp(`Email:\\s*${TAGS}([^\\s<]+@[^\\s<]+)`, 'i'));
  if (!m) m = (plain || strip(html)).match(/Email:\s*([^\s]+@[^\s]+)/i);
  if (!m && $json.from_address) {
    // fallback to parsed header if available
    const e = String($json.from_address).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
    if (e) m = [, e[0]];
  }
  if (m) lead_email = toStr(m[1]).toLowerCase();
}

// --- display name / given / family ---
let display_name = '';
{
  let m = src.match(new RegExp(`From:\\s*${TAGS}([^<\\n\\r]+)`, 'i'));
  if (!m) m = (plain || strip(html)).match(/From:\s*([^\n\r]+)/i);
  if (!m && $json.from_address) {
    // try to pull name from "Name <email>" pattern
    const m2 = String($json.from_address).match(/^([^<]+)<[^>]+>$/);
    if (m2) m = [, m2[1]];
  }
  if (m) display_name = t(m[1]);
}

let given_name = '';
let family_name = '';
if (display_name) {
  const parts = display_name.split(/\s+/).filter(Boolean);
  given_name = parts.shift() || '';
  family_name = parts.join(' ');
}

// --- phone (optional) ---
let lead_phone = null;
{
  let m = src.match(new RegExp(`Phone:\\s*${TAGS}([^<\\n\\r]+)`, 'i'));
  if (!m) m = (plain || strip(html)).match(/Phone:\s*([^\n\r]+)/i);
  if (m) {
    const ph = toStr(m[1]).replace(/[^\d+ ]/g,'').trim();
    if (ph) lead_phone = ph;
  }
}

// --- message/comments (robust with fallbacks) ---
let lead_message = '';
{
  let m = src.match(new RegExp(`Message:\\s*${TAGS}([\\s\\S]*?)(?:<\\/p>|<\\/div>|<\\/tr>|$)`, 'i'));
  if (!m) {
    const textAll = (plain || strip(html)).replace(/\r/g,'');
    m = textAll.match(/Message:\s*([\s\S]*?)$/i)
      || textAll.match(/Comments:\s*([\s\S]*?)$/i)
      || textAll.match(/Enquiry:\s*([\s\S]*?)$/i);
  }
  // final fallback: whole plain or stripped html
  lead_message = t(strip(m ? m[1] : (plain || strip(html)))) || '';
}

// --- property title / subject (stronger heuristics) ---
let property_title = '';
{
  // 1) explicit “Enquiry for …” in body/html
  let m = src.match(new RegExp(`Enquiry\\s+for\\s*${TAGS}([^<\\n\\r]+)`, 'i'));
  // 2) label “Property:” in body
  if (!m) m = src.match(new RegExp(`Property:\\s*${TAGS}([^<\\n\\r]+)`, 'i'));
  // 3) try raw_subject patterns
  if (!m && $json.raw_subject) {
    const rs = String($json.raw_subject).trim();
    m = rs.match(/Enquiry\s+for\s+(.+)$/i)
      || rs.match(/^\s*\[([^\]]+)\]/)           // [12 Smith St]
      || rs.match(/^([^–-]+)\s*[–-]\s*.*$/);    // "12 Smith St - something"
    if (m) { property_title = t(m[1]); }
  }
  // 4) if still empty, try subject headers from parsed fields
  if (!property_title) {
    const subj = toStr($json.subject) || toStr($json.raw_subject);
    if (subj) {
      let mm = subj.match(/^\s*\[([^\]]+)\]/) || subj.match(/^([^–-]+)\s*[–-]\s*.*$/);
      if (mm) property_title = t(mm[1]);
    }
  }
  // 5) if still empty, try simple address-like capture from message
  if (!property_title) {
    const txt = (plain || strip(html));
    const mm = txt.match(/\b(\d{1,4}\s+[A-Za-z][A-Za-z\s.'-]+(?:St|Street|Rd|Road|Ave|Avenue|Dr|Drive|Blvd|Court|Ct|Way|Lane|Ln)\b.*?)/i);
    if (mm) property_title = t(mm[1]);
  }
  // 6) fallback
  if (!property_title) property_title = 'the property';
}

const subject =
  property_title && !/^enquiry\s+for/i.test(toStr($json.raw_subject))
    ? `Enquiry for ${property_title}`
    : ($json.raw_subject || $json.subject || 'Property enquiry');

// --- provider identifiers ---
let provider_message_id = null;
{
  let m = src.match(new RegExp(`Domain\\s*ID[:\\s]*${TAGS}([0-9]+)`, 'i'));
  if (!m) m = (plain || strip(html)).match(/Domain\s*ID[:\s]*([0-9]+)/i);
  if (m) provider_message_id = t(m[1]) || null;
}
let provider_ref = null;
{
  let m = src.match(new RegExp(`Your\\s+ref:\\s*${TAGS}([a-z0-9-]+)`, 'i'));
  if (!m) m = (plain || strip(html)).match(/Your\s+ref:\s*([a-z0-9-]+)/i);
  if (m) provider_ref = t(m[1]) || null;
}

// --- timestamp ---
const received_at = $json.outer_date ? new Date($json.outer_date).toISOString() : $now.toISO();

// --- body hash (FNV-1a 64-bit) for dedupe ---
function fnv1a64Hex(str){
  let h = BigInt('0xcbf29ce484222325');
  const prime = BigInt('0x100000001b3');
  for (let i=0;i<str.length;i++){
    h ^= BigInt(str.charCodeAt(i));
    h = (h * prime) & BigInt('0xFFFFFFFFFFFFFFFF');
  }
  return h.toString(16).padStart(16,'0');
}
const norm = (toStr(plain) || strip(html)).toLowerCase().replace(/\s+/g,' ').slice(0,4000);
const body_hash = fnv1a64Hex(norm);

// provider_message_id final
const provider_message_id_final =
  provider_message_id || $json.outer_message_id || `EML:${body_hash}`;

// --- output (ensure strings or nulls, not "undefined") ---
return {
  json: {
    lead_email: lead_email || '',
    display_name: display_name || '',
    given_name: given_name || '',
    family_name: family_name || '',
    lead_phone: lead_phone || null,
    lead_message: lead_message || null,
    property_title: property_title || null,
    subject,
    provider_message_id: provider_message_id_final,
    provider_ref,
    received_at,
    body_hash,
    body_html: toStr(html) || null,
    body_plain: toStr(plain) || null
  }
};

// Read binary from previous node (Download → "data")
const bin = $input.item.binary?.data?.data;
if (!bin) throw new Error('No binary "data" found from Download node.');
const raw = Buffer.from(bin, 'base64').toString('utf8');

// ---- headers ----
const headerBlock = (raw.match(/^[\s\S]*?\r?\n\r?\n/) || [''])[0];
const eml_headers = {};
for (const line of headerBlock.split(/\r?\n/)) {
  const m = line.match(/^([^:]+):\s*(.*)$/);
  if (m) eml_headers[m[1].toLowerCase()] = m[2];
}
const outer_message_id = eml_headers['message-id'] || null;
const outer_date = eml_headers['date'] || null;
const raw_subject = eml_headers['subject'] || null;

// ---- bodies (prefer HTML, fall back to plain) ----
let html = '', plain = '';
const mHtml = raw.match(/Content-Type:\s*text\/html[\s\S]*?\r?\n\r?\n([\s\S]*?)\r?\n--/i);
if (mHtml) html = mHtml[1].trim();
if (!html) {
  const loose = raw.match(/<html[\s\S]*<\/html>/i);
  if (loose) html = loose[0];
}
if (!html) {
  const bodyStart = headerBlock.length;
  plain = raw.slice(bodyStart).trim();
}
if (!plain && html) {
  // quick strip
  plain = html.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
}

return {
  json: { eml_headers, html, plain, outer_message_id, outer_date, raw_subject }
};

