parameters.jsCode:
return items.map(item => {
  const row = item.json;
  const snap = row.rubric_snapshot || {};
  row.rubric_total_score = snap.total_score ?? null;

  // flatten rubric fields
  if (snap.fields && typeof snap.fields === 'object') {
    for (const [k, v] of Object.entries(snap.fields)) {
      const key = k.replace(/[^\w]+/g, "_"); // safe header
      row[`${key}_value`] = v?.value ?? null;
      row[`${key}_points`] = v?.points ?? null;
      row[`${key}_class`] = v?.classification ?? null;
    }
  }

  // flatten context_fields
  if (snap.context_fields && typeof snap.context_fields === 'object') {
    for (const [k, v] of Object.entries(snap.context_fields)) {
      const key = k.replace(/[^\w]+/g, "_");
      if (Array.isArray(v)) {
        // join arrays into string
        row[`ctx_${key}`] = v.join(" | ");
      } else if (typeof v === 'object' && v !== null) {
        // stringify nested objects
        row[`ctx_${key}`] = JSON.stringify(v);
      } else {
        row[`ctx_${key}`] = v ?? null;
      }
    }
  }

  // flatten questions (if exist)
  row.rubric_questions = Array.isArray(snap.questions)
    ? snap.questions.join(" | ")
    : null;

  delete row.rubric_snapshot;
  return { json: row };
});

