// Compose Off-topic Reply — v10.1.1 (hardened, minimal-behavior change)

var ADD_SIGNATURE = true;

// helpers
function toStr(x){ return (x == null ? '' : String(x)); }
function stripHtml(h){
  return toStr(h)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g,' ')
    .replace(/\s+/g,' ')
    .trim();
}
function squeeze(s){ return toStr(s).replace(/\s+/g,' ').trim(); }
function cleanBody(raw){
  var t = stripHtml(raw || '');
  t = t.replace(/^-{2,}\s*original message[\s\S]*$/im, '')
       .replace(/^on .*wrote:\s*[\s\S]*$/im, '')
       .replace(/from:\s.*\nsubject:\s.*\n[\s\S]*$/im, '');
  t = t.replace(/\b(unsubscribe|privacy policy|confidentiality notice|view in browser)\b/ig, '');
  t = t.replace(/[\u200B-\u200D\uFEFF]/g, '');
  return squeeze(t);
}
function fullDisplayName(msg){
  var n = (msg?.replyTo?.[0]?.emailAddress?.name)
       || (msg?.from?.emailAddress?.name) || '';
  return String(n).replace(/["<>]/g,'').replace(/\s+/g,' ').trim();
}
function ensureCRLF(s){ return toStr(s).split('\n').join('\r\n'); }
function escapeHtml(s){
  var map = { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' };
  return String(s || '').replace(/[&<>"']/g, function(c){ return map[c]; });
}
function cap120(s){ s = toStr(s).trim(); return s.length>120 ? s.slice(0,120) : s; }

// source
var upstream = $items('Get Message (Graph)')?.[$itemIndex]?.json || null;
var cur = $json || {};
var src = upstream || cur;

// getters
function getSubject(o){ return o?.subject || o?.message?.subject || 'Your email'; }
function getBodyRaw(o){
  if (o?.uniqueBody?.content) return o.uniqueBody.content;
  if (o?.message?.uniqueBody?.content) return o.message.uniqueBody.content;
  if (o?.body?.content) return o.body.content;
  if (o?.message?.body?.content) return o.message.body.content;
  if (typeof o?.body === 'string') return o.body;
  if (o?.bodyPreview) return o.bodyPreview;
  if (o?.textBody) return o.textBody;
  if (o?.htmlBody) return o.htmlBody;
  if (o?.data?.body?.content) return o.data.body.content;
  return '';
}
function getFromAddress(o){
  return o?.from?.emailAddress?.address
      || o?.sender?.emailAddress?.address
      || '';
}
function getReplyToAddress(o){
  var arr = o?.replyTo || o?.message?.replyTo;
  if (Array.isArray(arr) && arr.length){
    var a = arr.map(x => x?.emailAddress?.address || x?.address || '').find(Boolean);
    if (a) return { addr: a, source: 'replyTo' };
  }
  var hdrs = o?.internetMessageHeaders || o?.message?.internetMessageHeaders;
  if (Array.isArray(hdrs)){
    var h = hdrs.find(hh => String(hh?.name||'').toLowerCase() === 'reply-to');
    if (h?.value){
      var m = String(h.value).match(/<([^>]+)>/);
      return { addr: (m && m[1]) || String(h.value).split(',')[0].trim(), source: 'headers' };
    }
  }
  var fallback = o?.sender?.emailAddress?.address
              || o?.from?.emailAddress?.address
              || o?.message?.from?.emailAddress?.address
              || '';
  return { addr: fallback, source: fallback ? 'from_fallback' : 'missing' };
}

// addresses & subject
var subj = getSubject(src);
var rawBody = getBodyRaw(src);
var fromAddr = String(getFromAddress(src) || '').toLowerCase();
var r = getReplyToAddress(src);
var replyToAddr = String((r && r.addr) || '').toLowerCase();

var toAddr = replyToAddr || fromAddr;
var OUR_DOMAIN_RE = /@(austrump|arcsage|communication\.microsoft)\./i;
var targetForDb = (!replyToAddr || OUR_DOMAIN_RE.test(replyToAddr)) ? fromAddr : replyToAddr;

var subject = (/^\s*(re|fwd|fw):/i.test(subj || '')) ? subj : ('Re: ' + (subj || 'Your email'));
subject = cap120(subject);

// gather DB rows
function collectRows(nodeName){
  var arr = $items(nodeName) || [];
  var flat = [];
  for (var it of arr){
    var j = (it && (it.json ?? it)) || null;
    if (!j) continue;
    if (Array.isArray(j)) flat.push(...j);
    else flat.push(j);
  }
  return flat;
}
var rowsA = collectRows('Resolve Client (SELECT by sender)');
var rowsB = collectRows('Touch Client (IN, inserted) B');
var allRows = rowsA.concat(rowsB);

// pick client & salutation
function normEmail(e){
  e = String(e || '').trim().toLowerCase();
  if (!e) return '';
  var parts = e.split('@'); var local = parts[0], domain = parts[1];
  if (!local || !domain) return e;
  if (/^(gmail|googlemail)\.com$/.test(domain)) {
    var base = local.split('+')[0].replace(/\./g,'');
    return base + '@' + domain;
  }
  return local + '@' + domain;
}
function pickClientRecord(){
  var clientId =
    (toStr($json.client_id).trim()) ||
    (toStr(rowsA[0]?.client_id).trim()) ||
    (toStr(rowsB[0]?.client_id).trim());
  if (clientId) {
    var byId = allRows.find(r => toStr(r.client_id).trim() === clientId);
    if (byId) return { rec: byId, source: 'client_id' };
  }
  if (targetForDb) {
    var eExact = allRows.find(r => String(r.email || '').toLowerCase() === targetForDb);
    if (eExact) return { rec: eExact, source: 'email_exact' };
    var eRow = allRows.find(r => normEmail(r.email) === normEmail(targetForDb));
    if (eRow) return { rec: eRow, source: 'email_normalized' };
  }
  if (allRows.length === 1) return { rec: allRows[0], source: 'single_row_fallback' };
  return { rec: null, source: 'none' };
}
var picked = pickClientRecord();
var clientRec = picked.rec;
var nameSource = picked.source;

var displayFromJson = $json.display_name || $json.client_display_name;
var givenFromJson   = $json.given_name   || $json.client_given_name;
var familyFromJson  = $json.family_name  || $json.client_family_name;

var name = '';
if (displayFromJson) {
  name = String(displayFromJson).trim();
} else if (givenFromJson || familyFromJson) {
  name = [toStr(givenFromJson).trim(), toStr(familyFromJson).trim()].filter(Boolean).join(' ');
} else if (clientRec) {
  if (clientRec.display_name) name = String(clientRec.display_name).trim();
  else if (clientRec.given_name || clientRec.family_name)
    name = [toStr(clientRec.given_name).trim(), toStr(clientRec.family_name).trim()].filter(Boolean).join(' ');
}
if (!name) {
  var header = fullDisplayName(src);
  if (header) name = header;
}
if (!name) {
  var local = String(toAddr || '').split('@')[0] || '';
  name = local ? local.replace(/[._-]+/g,' ').replace(/\d+/g,' ').replace(/\s+/g,' ')
               .replace(/\b\w/g,function(c){return c.toUpperCase();})
               : 'there';
}
var salutation = name;

// language & flags
var bodyText = cleanBody(rawBody);
var subjText = toStr(subj || '');
var combinedText = (subjText + ' ' + bodyText).trim();

var containsHan = /[\u4E00-\u9FFF]/.test(combinedText);
var lang = ($json.lang || '').toLowerCase() || (containsHan ? 'zh' : 'en');
if (lang && lang.startsWith('zh')) lang = 'zh';

var hardOpt = $json._hard_opt_out === true;
var softOptLocal =
  /(?:no\W*longer\W*interested|not\W*interested|no\W*longer\W*looking|please\W*close\W*my\W*enquiry|found\W*(?:a|our)\W*(?:place|home|house|apartment)|already\W*(?:bought|purchased)|we(?:'|’)?ve\W*settled|settlement\W*complete)/i
    .test(combinedText)
  || /(不感兴趣|没兴趣|不再感兴趣|暂不考虑|先不考虑|不用了|不需要了|暂不需要|已经买(好|到)?了?房(子)?|已经成(交|交割)|已经(完成)?过户|已经签约|已经找到了?房(子)?|不再(找|看)房)/.test(combinedText);
var softOpt = ($json._soft_opt_out === true) || softOptLocal;

var autoRep = $json._auto_reply === true;
var safetyBlock = $json._safety_block === true;

// choose template
var paras = [];
if (safetyBlock || hardOpt) {
  // skip
} else if (softOpt) {
  paras = (lang === 'zh')
    ? [
        '收到你的来信，了解你目前不再继续这次咨询（或已完成买房）。',
        '如果以后有需要（例如在墨尔本或布里斯班买房），随时联系，我们很乐意协助。'
      ]
    : [
        'Thanks for letting us know you’re not continuing at this stage (or have already purchased).',
        'If your plans change and you’d like help buying in Melbourne or Brisbane, we’re here anytime.'
      ];
} else {
  paras = (lang === 'zh')
    ? [
        '感谢你的来信。这个邮箱主要处理买房相关咨询（墨尔本与布里斯班）。',
        '如果你正在考虑买房，请告诉我们大概的区域/郊区、预算范围、房屋类型以及时间计划，我们会尽快给出建议和下一步安排。'
      ]
    : [
        'Thanks for your message. This inbox looks after buying enquiries (Melbourne & Brisbane).',
        'If buying is on your radar, share your suburb/area, an approximate budget, the type of place you’re considering, and your timeline, and we’ll suggest next steps.'
      ];
}

var hasContent = paras.length > 0;

// TEXT
var textLines = hasContent ? ['Hi ' + salutation + ',', ''] : [];
for (var i = 0; i < paras.length; i++){
  textLines.push(paras[i]);
  if (i < paras.length - 1) textLines.push('');
}
if (ADD_SIGNATURE && hasContent) textLines.push('', 'Warm regards,', 'Austrump Glen Team');
var body = ensureCRLF(textLines.join('\n'));

// HTML
