// Normalize v10.1.1 (hardened)
function toBool(x) {
  if (typeof x === 'boolean') return x;
  if (typeof x === 'number') return Number.isFinite(x) && x !== 0;
  if (x == null) return false;
  const s = String(x).trim().toLowerCase();
  if (['false','0','off','no'].includes(s)) return false;
  return ['true','t','yes','y','on','1'].includes(s);
}
function normConfidence(x) {
  if (x == null || x === '') return 0.6; // sensible default
  let s = String(x).trim();
  if (s.endsWith('%')) {
    const pct = Number(s.slice(0, -1));
    if (Number.isFinite(pct)) return Math.max(0, Math.min(1, pct / 100));
  }
  let n = Number(s);
  if (!Number.isFinite(n)) return 0.6;
  // Accept 0..1, or 1..100 (scale down)
  if (n > 1 && n <= 100) n = n / 100;
  if (n < 0) n = 0;
  if (n > 1) n = 1;
  return n;
}

