function normalizePlain(s = '') {
  let t = stripHtml(s);
  t = t.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').replace(/[ \t]+\n/g, '\n').trim();
  return t;
}

function sanitizeNoDashesPreserveRanges(s = '') {
  const R = /(\d\s*[–—-]\s*\d)/g;
  const tokens = [];
  const marked = String(s).replace(R, (m) => {
    tokens.push(m);
    return `__RANGE_${tokens.length - 1}__`;
  });
  const noD = marked.replace(/[–—-]/g, ' ');
  let out = noD;
  tokens.forEach((tok, i) => {
    out = out.replace(`__RANGE_${i}__`, tok);
  });
  return out.replace(/\s{2,}/g, ' ').replace(/\s*\n\s*/g, '\n').trim();
}

function cap120Chars(s) {
  const str = String(s || '');
  return str.length > 120 ? str.slice(0, 117) + '…' : str;
}

function looksLikeThreadSubject(s) {
  return /^\s*(re|fw|fwd)\s*:/i.test(String(s || ''));
}

function djb2Hash(str = '') {
  let h = 5381;
  const s = String(str);
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) + h) + s.charCodeAt(i);
    h |= 0;
  }
  return String(h >>> 0);
}

function sentenceSplit(text) {
  const zh = /[\u4e00-\u9fff]/.test(String(text || ''));
  const re = zh ? /(?<=[。！？?])/ : /(?<=[.!?])/;
  return String(text || '').split(re).map((x) => x.trim()).filter(Boolean);
}

function sentenceSplit2(text) {
