function unionList(a, b) {
  const set = new Set();
  for (const x of (a || [])) set.add(String(x).toLowerCase());
  const out = (a || []).slice();
  for (const y of (b || [])) {
    const yl = String(y).toLowerCase();
    if (!set.has(yl)) {
      set.add(yl);
      out.push(y);
    }
  }
  return out;
}

function langRatio(text = '') {
  const s = String(text || '');
  let cjk = 0;
  let latin = 0;
  for (const ch of s) {
    if (/[㐀-\u9fff]/.test(ch)) cjk++;
    else if (/[A-Za-z]/.test(ch)) latin++;
  }
  const total = cjk + latin;
  const zhRatio = total ? (cjk / total) : 0;
  return { zh: zhRatio, en: 1 - zhRatio };
}

function isTargetLang(text, target) {
  const r = langRatio(text);
  return target === 'zh' ? r.zh >= 0.6 : r.en >= 0.6;
}

function normalizePhoneAU(raw) {
  if (!raw) return null;
  let s = String(raw).replace(/[^\d+]/g, '');
  // Australia
  if (s.startsWith('+61')) {
    s = s.replace(/^(\+61)0?/, '$1');
    return s;
  }
  if (/^04\d{8}$/.test(s)) return '+61' + s.slice(1);
  if (/^4\d{8}$/.test(s)) return '+61' + s;
  if (/^0\d{9}$/.test(s)) return '+61' + s.slice(1);
  // China mobile (+86 1XXXXXXXXXX or 1XXXXXXXXXX)
  if (s.startsWith('+86')) {
    s = s.replace(/^(\+86)0?/, '$1');
    if (/^\+861[3-9]\d{9}$/.test(s)) return s;
  }
  if (/^1[3-9]\d{9}$/.test(s)) return '+86' + s;
  // No generic fallback: if it doesn't clearly match AU/China mobile formats, treat as invalid
  return null;
}

function extractPhoneFromText(text = '') {
  const s = String(text || '');
  const re = /(\+61\s?4\d{2}\s?\d{3}\s?\d{3}|0?4\d{2}\s?\d{3}\s?\d{3}|0\d{1,2}\s?\d{4}\s?\d{4}|\+61\s?\d{1,2}\s?\d{4}\s?\d{4})(?!\d)/g;
  let m;
  let best = null;
  while ((m = re.exec(s))) {
    const n = normalizePhoneAU(m[1]);
    if (n && (!best || n.length > best.length)) best = n;
  }
  return best;
}

function stripCodeFences(s = '') {
  const m = String(s).match(/```(?:json)?\s*([\s\S]*?)```/i);
  return m ? m[1] : String(s);
}

function cleanJsonish(s = '') {
  let t = String(s);
  t = stripCodeFences(t);
  t = t.replace(/^\uFEFF/, '');
  t = t.replace(/^\s*semantically_similar_to_user_input\s*$/gm, '');
  t = t.replace(/,(\s*[}\]])/g, '$1');
  return t.trim();
}

function safeParseJSON(s) {
  if (!s) return null;
  if (typeof s !== 'string') return s;
  const cleaned = cleanJsonish(s);
  try { return JSON.parse(cleaned); } catch { }
  const i = cleaned.indexOf('{');
  const j = cleaned.lastIndexOf('}');
  if (i >= 0 && j > i) {
    const core = cleaned.slice(i, j + 1)
      .replace(/^\s*semantically_similar_to_user_input\s*$/gm, '')
      .replace(/,(\s*[}\]])/g, '$1');
    try { return JSON.parse(core); } catch { }
  }
  return null;
}

