function enforceTwoQuestionMarks(text) {
  let t = String(text || '');
  const qIdxs = [];
  for (let i = 0; i < t.length; i++) {
    if (t[i] === '?' || t[i] === '？') qIdxs.push(i);
  }
  if (qIdxs.length > 2) {
    const keep = new Set([qIdxs[0], qIdxs[1]]);
    let outStr = '';
    for (let i = 0; i < t.length; i++) {
      const ch = t[i];
      if ((ch === '?' || ch === '？') && !keep.has(i)) outStr += '.';
      else outStr += ch;
    }
    t = outStr;
  }
  const paras = String(t).split(/\n{2,}/).map((x) => stripWeirdPTags(x).trim()).filter(Boolean);
  let lastParaIdx = -1;
  for (let i = 0; i < paras.length; i++) {
    const idx = Math.max(paras[i].lastIndexOf('?'), paras[i].lastIndexOf('？'));
    if (idx >= 0) lastParaIdx = i;
  }
  if (lastParaIdx >= 0 && lastParaIdx !== paras.length - 1) {
    const qPara = paras.splice(lastParaIdx, 1)[0];
    paras.push(qPara);
  }
  if (paras.length) {
    const lp = paras[paras.length - 1];
    const cut = Math.max(lp.lastIndexOf('?'), lp.lastIndexOf('？'));
    if (cut >= 0) paras[paras.length - 1] = lp.slice(0, cut + 1).trim();
  }
  return paras.join('\n\n');
}

