    for (const s of sents) {
      if (!SOURCE_SENTENCES.has(s)) continue;
      buf.push(s);
      if (buf.join(' ').length > 240 || buf.length >= 6) {
        paras2.push(buf.join(' '));
        buf = [];
        if (paras2.length === 3) break;
      }
    }
    if (buf.length) paras2.push(buf.join(' '));
    return paras2.slice(0, 3);
  }

  function dedupeWithinParagraph(p) {
    const sents = sentenceSplit(p);
    const seen = new Set();
    const keep = [];
    for (const s of sents) {
      if (!SOURCE_SENTENCES.has(s)) continue;
      const k = s.toLowerCase().replace(/\s+/g, ' ').trim();
      if (!seen.has(k)) {
        seen.add(k);
        keep.push(s);
      }
    }
    return keep.join(' ').trim();
  }

  function dedupeSentLevel(parasArr, ...sentLists) {
    const all = new Set();
    for (const list of (sentLists || [])) {
      for (const s of (list || [])) all.add(String(s).toLowerCase());
    }
    return parasArr.map((p) => {
      const kept = sentenceSplit(p).filter((s) => SOURCE_SENTENCES.has(s) && !all.has(s.toLowerCase()));
      return kept.join(' ').trim();
    }).filter(Boolean);
  }

  function dedupeAgainstText(parasArr, lastOutText) {
    const lastSents = lastOutText ? new Set(sentenceSplit(lastOutText).map((s) => s.toLowerCase())) : new Set();
    const outArr = [];
    for (const p of parasArr) {
      const keepSents = sentenceSplit(p).filter((s) => SOURCE_SENTENCES.has(s) && !lastSents.has(s.toLowerCase()));
      const merged = keepSents.join(' ').trim();
      if (merged) outArr.push(merged);
    }
    return outArr;
  }

