function normAddr(a) { const s = String(a || '').trim(); return s.includes(' ') ? s : s.toLowerCase(); }
function escapeHtml(s) { return String(s || '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
function sanitizeNoDashesPreserveRanges(s = '') {
  const R = /(\d\s*[–—-]\s*\d)/g;
  const tokens = [];
  const marked = String(s).replace(R, (m) => { tokens.push(m); return `__RANGE_${tokens.length - 1}__`; });
  const noDashes = marked.replace(/[–—-]/g, ' ');
  let out = noDashes;
  tokens.forEach((tok, i) => { out = out.replace(`__RANGE_${i}__`, tok); });
  return out.replace(/\s{2,}/g, ' ').replace(/\s*\n\s*/g, '\n').trim();
}
function fixDashArtifacts(s = '') { return String(s).replace(/â€“/g, '–').replace(/â€”/g, '—'); }
