    (parsed.display_name || parsed.client_display_name || '').trim() ||
    (snapNode.client_display_name || '').trim() ||
    (snapNode.display_name || '').trim();

  const snapGiven = (snapNode.given_name || '').trim();
  const snapFamily = (snapNode.family_name || '').trim();
  const snapFull = (snapGiven || snapFamily) ? `${snapGiven} ${snapFamily}`.trim() : '';

  if (snapDisplay || snapFull) {
    return snapDisplay || snapFull;
  }

  // 2) Then use Resolve Client (SELECT by sender) result for this item
  let rc = null;
  try {
    const arr = $items("Resolve Client (SELECT by sender)");
    if (Array.isArray(arr) && arr[$itemIndex] && arr[$itemIndex].json) {
      rc = arr[$itemIndex].json;
    } else if ($node["Resolve Client (SELECT by sender)"]?.json) {
      rc = $node["Resolve Client (SELECT by sender)"].json;
    }
  } catch (e) {
    rc = rc || null;
  }

  // If that node ever returns an array, pick the row that matches this email
  if (Array.isArray(rc)) {
    const emailLower =
      (toCustomer || parsed.client_email || ub.email || '').toLowerCase();
    if (emailLower) {
      const match = rc.find(r => String(r.email || '').toLowerCase() === emailLower);
      rc = match || rc[0] || null;
    } else {
      rc = rc[0] || null;
    }
  }

  const rcDisplay = (rc?.display_name || '').trim();
  const rcGiven = (rc?.given_name || '').trim();
  const rcFamily = (rc?.family_name || '').trim();
  const rcFull = (rcGiven || rcFamily) ? `${rcGiven} ${rcFamily}`.trim() : '';

  const displayFromRc =
    rcDisplay ||
    rcFull ||
    (ctxBuild?._display_name_real || '').trim() ||
    (ub.display_name || '').trim() ||
    (ub.client_display_name || '').trim() ||
    (snap.display_name || '').trim();

  if (displayFromRc) return displayFromRc;

  // 3) Fallback from email local part
  const addr = toCustomer || rc?.email || ub.email || '';
  if (addr) {
    const local = String(addr).split('@')[0] || '';
    if (local) {
      const parts = local.replace(/[._]/g, ' ').split(/\s+/);
      const titled = parts
        .filter(Boolean)
        .map(w => w.charAt(0).toUpperCase() + w.slice(1))
        .join(' ');
      if (titled) return titled;
    }
  }

  // 4) Final fallback from Graph headers
  const hdr = m?.replyTo?.[0]?.emailAddress?.name || m?.from?.emailAddress?.name || '';
  const clean = String(hdr).replace(/[<>"]/g, '').replace(/\s+/g, ' ').trim();
  return clean || '';
