// Normalize context field values to English for internal reports
function normalizeValueForReport(value) {
  if (typeof value === 'string') {
    // Check if entire value is a known Chinese phrase
    if (CONTEXT_TRANSLATIONS[value]) {
      return CONTEXT_TRANSLATIONS[value];
    }
    // Check if value contains Chinese and translate parts
    for (const [zh, en] of Object.entries(CONTEXT_TRANSLATIONS)) {
      if (value.includes(zh)) {
        value = value.replace(zh, en);
