  if (key === 'suburbs_list') return 'Suburbs (interest)';
  if (key === 'visited_suburbs_list') return 'Visited / inspected suburbs';
  if (key === 'human_contact_phone') return 'Human contact phone';
  if (key === 'phone_asked') return 'Phone asked';
  if (key === 'city') return 'City';
  if (key === 'noise_preference') return 'Noise preference';
  if (key === 'orientation_preference') return 'Orientation preference';
  return key
    .split('.')
    .map(p => p.replace(/_/g, ' ').trim())
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
