    if (SKIP_KEYS.has(k) || k.startsWith('_')) continue;

    const path = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      out.push(...flattenPretty(v, path));
    } else {
      const keyPretty = prettifyKey(path);
      let valPretty = v;
      if (Array.isArray(valPretty)) valPretty = valPretty.join('; ');
      if (valPretty === true) valPretty = 'Yes';
      if (valPretty === false) valPretty = 'No';
      valPretty = String(valPretty ?? '').trim();
      // Normalize Chinese values to English for internal reports
      valPretty = normalizeValueForReport(valPretty);
      if (!valPretty) valPretty = 'Not provided';
      out.push([keyPretty, valPretty]);
