  let evidence = val;
  if (!evidence) {
    const lc = key.toLowerCase();
    if (/budget/.test(lc)) evidence = ctxFields.budget_text || ctxFields.budget || '';
    else if (/suburb|location|zone/.test(lc)) evidence = ctxFields.suburbs || ctxFields.suburbs_list || ctxFields.schools_interest || '';
    else if (/timeline|settle/.test(lc)) evidence = ctxFields.timeline_text || '';
