// Normalize Recipient (per item) — v10.0.1 (hardened)
function extractEmail(x){
  if (!x) return '';
  const s = String(x).trim();
  // Matches Name <email@domain> or just email
  const m = s.match(/<\s*([^>]+)\s*>/);
  const addr = (m ? m[1] : s).trim();
  return addr.toLowerCase();
}
function firstNonEmpty(arr){
  for (const v of arr){
    const s = (Array.isArray(v) ? v.join(',') : String(v || '')).trim();
    if (!s) continue;
    // split by common separators then return first token
    const tok = s.split(/[;,]/).map(t => t.trim()).filter(Boolean)[0];
    if (tok) return tok;
  }
  return '';
}

const g   = $items('Get Message (Graph)')[$itemIndex]?.json ?? {};
const rsv = $items('Resolve Client (SELECT by sender)')[$itemIndex]?.json ?? {};

// 1) Mailbox we SEND FROM
let mailboxRaw =
  (rsv && rsv.mailbox) ? String(rsv.mailbox) : '';
if (!mailboxRaw.trim()) mailboxRaw = 'austrump@arcsage.com.au';
const mailbox = extractEmail(mailboxRaw) || 'austrump@arcsage.com.au';

// 2) Recipient we SEND TO (prefers explicit $json.to)
const toRaw = firstNonEmpty([
  $json.to,
  g?.replyTo?.[0]?.emailAddress?.address,
  g?.from?.emailAddress?.address
]);
const to = extractEmail(toRaw);

// 3) Graph endpoint
const sendUrl = (mailbox === 'me')
  ? 'https://graph.microsoft.com/v1.0/me/sendMail'
  : 'https://graph.microsoft.com/v1.0/users/' + encodeURIComponent(mailbox) + '/sendMail';

// 4) Guards
const _mailbox_is_me = (mailbox === 'me');
const _skip_customer = Boolean($json._skip_customer) || !to;

return {
  json: {
    ...$json,
    mailbox,
    to,
    sendUrl,
    _skip_customer,
    _mailbox_is_me
  }
};

// ###Choose Reply Result — v10.1.3 (adds HANDOFF priority + ALREADY-READY branch)
// - Preserves READY/NOT_READY merge logic
// - HANDOFF takes precedence
// - Adds required: already-ready => notify-only, no client email
// - No irrelevant changes (minimum change)

function safeItem(nodeName, idx) {
  try {
    const a = $items(nodeName);
    return a && a.length > idx ? a[idx] : null;
  } catch { return null; }
}
function toStr(x){ return x == null ? '' : String(x); }
function extractEmail(addrLike){
  const s = toStr(addrLike).trim();
  if (!s) return '';
  const m = s.match(/<([^>]+)>/);
  const raw = (m && m[1]) || s;
  const first = raw.split(',')[0].trim();
  return first.replace(/^["']+|["']+$/g,'').trim();
}
function firstEmailFromRecipients(arr){
  if (!Array.isArray(arr)) return '';
  for (const r of arr){
    const e = r?.emailAddress?.address || r?.address || r?.email || '';
    const clean = extractEmail(e);
    if (clean) return clean;
  }
  return '';
}
function getSenderEmail(msg){
  const fromTop = msg?.from?.emailAddress?.address;
  const replyToTop = firstEmailFromRecipients(msg?.replyTo);
  const fromMsg = msg?.message?.from?.emailAddress?.address;
  const replyToMsg = firstEmailFromRecipients(msg?.message?.replyTo);
  const ubFallback = base?.USER_BLOCK?.from_email;
  const pick = replyToTop || replyToMsg || fromTop || fromMsg || ubFallback || '';
  return extractEmail(pick);
}

// Pick upstream branch payloads
const ready = safeItem('Reply Ready Customer', $itemIndex);
const notOk = safeItem('Reply Not Ready Customer', $itemIndex);
const base = (ready?.json) ?? (notOk?.json) ?? ($json ?? {});

// Graph message
const g =
  safeItem('Get Message (Graph)', $itemIndex)?.json
  || safeItem('Get Message (Graph)1', $itemIndex)?.json
  || {};

// Bring in PF + Snapshot
const pf        = safeItem('Parse & Filter (Confidence Gate)', $itemIndex)?.json || {};
const snapshot  = safeItem('Rubric & Load Latest Snapshot', $itemIndex)?.json || {};
const snapCtx   = snapshot?.rubric_snapshot?.context_fields || {};

// HANDOFF detection
const handoffNow  = pf.human_requested === true || base.human_requested === true;
const seenBefore  = snapCtx?.human_requested === true;
const human_requested_first_time = Boolean(handoffNow && !seenBefore);

// Resolve mailbox
const mailboxResolved = toStr(base?.mailbox || 'austrump@arcsage.com.au')
  .trim()
  .toLowerCase();

// Resolve 'to'
let toResolved = toStr(base?.to || '').trim();
if (!toResolved && Array.isArray(base?.to)) {
  toResolved = extractEmail(base.to[0]);
}
if (!toResolved && typeof base?.to === 'string' && base.to.includes(',')) {
  toResolved = extractEmail(base.to.split(',')[0]);
}
if (!toResolved) {
  toResolved = getSenderEmail(g);
}
toResolved = extractEmail(toResolved).toLowerCase();

// prevent to == mailbox
if (toResolved && toResolved === mailboxResolved) {
  toResolved = '';
}

// Message ID fallback
const messageId =
  base.messageId
  || g.id
  || g.messageId
  || g.internetMessageId
  || '';

// Base output object
const out = {
  ...base,
  messageId,
  mailbox: mailboxResolved || 'austrump@arcsage.com.au',
  to: toResolved
};

// ========== HANDOFF PRECEDENCE ==========
if (handoffNow) {
  out.channel = 'HUMAN_NOTIFY';
  out.human_requested = true;
  out.human_requested_first_time = human_requested_first_time;
  out._skip_customer = true;   // NO customer send
  out._notify_only = true;     // internal team only
  out.kind = 'HANDOFF';
  return { json: out };
}

// ========== ALREADY-READY BRANCH (REQUIRED) ==========
// If the client was already ready BEFORE this turn,
// and they are STILL qualified now,
// → internal notify only, NO customer email.
if (pf.was_ready_before === true && pf.qualified === true) {
  out.channel = 'LLM';
  out._skip_customer = true;
  out._notify_only = true;
  out.kind = 'ALREADY_READY';
  return { json: out };
}

// ========== OTHERWISE, NORMAL READY / NOT READY LOGIC ==========
out.channel = out.channel || 'LLM';
return { json: out };

// Build SQL params — v10.1.3
// - Keeps v10.1.2 logic
// - Ensures new handoff flags & phone fields pass through
// - Merges context_fields from PF and current $json (handoff/phone) for UPDATE node
// - MINIMAL ADD: pass through _phone_updated so downstream can decide on subject tweak/notification

function itemJson(name) {
  try {
    const arr = $items(name);
    return (arr && arr.length > $itemIndex && arr[$itemIndex]?.json) ? arr[$itemIndex].json : {};
  } catch { return {}; }
}
function toArray(x) {
  if (!x) return [];
  if (Array.isArray(x)) return x;
  if (typeof x === 'object') return Object.values(x);
  if (typeof x === 'string') {
    try { const j = JSON.parse(x); return Array.isArray(j) ? j : []; } catch {}
    return x.split(',').map(s => s.trim()).filter(Boolean);
  }
  return [];
}
function num(x){ const n = Number(x); return Number.isFinite(n) ? n : 0; }

const pf   = itemJson('Parse & Filter (Confidence Gate)');
const snap = itemJson('Rubric & Load Latest Snapshot');

const client_id = pf.client_id || snap.client_id || null;

let asked_fields = [
  ...(toArray(pf.asked_fields)),
  ...(toArray(pf.target_fields))
];

const MAP = {
  'Budget': 'Budget Range',
  'Timeline': 'Timeline to Buy / Settle',
  'Finance/Pre-approval': 'Financing Status',
  'Suburbs/Areas': 'Locations / School Zones',
  'Beds/Bath/Parking': 'Property Brief (type / size / features)',
  'Settlement/Move-in': 'Timeline to Buy / Settle',
  'Must-haves': 'Property Brief (type / size / features)'
};
asked_fields = asked_fields.map(k => MAP[k] || k).filter(Boolean);

const style_used =
  (pf.strategy_style_used && String(pf.strategy_style_used).trim())
  || (pf.next_step?.strategy_style && String(pf.next_step.strategy_style).trim())
  || null;

const explicitDelta = num(pf.progress_delta);
const prevScore = num(snap.readiness_score ?? pf.prev_readiness_score);
const newScore  = num(pf.readiness_score ?? pf.proposed_total_score);
const computedDelta = Math.max(0, Math.round(newScore - prevScore));
const progress_delta_int = explicitDelta || computedDelta;

const refused_fields = Array.isArray(pf.refused_fields) ? pf.refused_fields : [];
const answered_fields = Array.isArray(pf.answered_fields) ? pf.answered_fields : [];
const internal_questions_bindings = Array.isArray(pf.internal_questions_bindings)
  ? pf.internal_questions_bindings.map(x => ({
      field: typeof x?.field === 'string' ? x.field : '',
      q: typeof x?.q === 'string' ? x.q : ''
    })).filter(b => b.field && b.q)
  : [];

const accepted_changes = Array.isArray(pf.accepted_changes) ? pf.accepted_changes : [];

// Merge/extend context_fields with handoff + phone cues coming from current $json
const addCtx = ($json && $json.context_fields) ? $json.context_fields : {};
const merged_context_fields = {
  ...(pf.context_fields || {}),
  ...(addCtx || {})
};

// Best-effort HANDOFF indicators
const human_requested = Boolean(
  pf.human_requested ||
  ($json && $json.human_requested === true) ||
  snap?.rubric_snapshot?.context_fields?.human_requested
);
const human_requested_first_time = Boolean(
  ($json && $json.human_requested_first_time === true) ||
  pf.human_requested_first_time
);
const human_reason = pf.human_reason || $json.human_reason || null;

// Phone signals (may be set by PF or Build Context)
const human_contact_phone =
  pf.human_contact_phone
  || $json.human_contact_phone
  || merged_context_fields?.human_contact_phone
  || null;

// ==== MINIMAL ADD: passthrough of phone-update flag ====
const _phone_updated = pf._phone_updated === true;

return {
  json: {
    client_id,
    asked_fields_json: JSON.stringify(asked_fields || []),
    style_used,
    progress_delta_int,
    context_fields: {
      ...merged_context_fields,
      ...(human_requested ? { human_requested: true } : {}),
      ...(human_requested_first_time ? { human_requested_first_time: true } : {}),
      ...(human_reason ? { human_reason } : {}),
      ...(human_contact_phone ? { human_contact_phone } : {})
    },
    progress_delta_map: pf.progress_delta_map || {},
    _last_body_hash_new: pf._last_body_hash_new || null,
    _repeat_body_runs_new: Number.isFinite(pf._repeat_body_runs_new) ? pf._repeat_body_runs_new : 0,
    _asked_log_turns_delta: pf._asked_log_turns_delta || {},
    _last_out_sents_new: Array.isArray(pf._last_out_sents_new) ? pf._last_out_sents_new.slice(0,12) : [],
    _said_sents_new: Array.isArray(pf._said_sents_new) ? pf._said_sents_new.slice(0,60) : [],
    _last_in_id_new: pf._last_in_id_new || null,
    _score_history_append: pf._score_history_append || null,
    _field_history_append: pf._field_history_append || {},
    _merged_fields_passthrough: pf.merged_fields || {},
    _total_score_passthrough: num(pf.proposed_total_score || pf.readiness_score || 0),
    refused_fields,
    answered_fields,
    internal_questions_bindings,
    _do_not_ask_fields: Array.isArray(pf._do_not_ask_fields) ? pf._do_not_ask_fields : [],
    _reply_type: typeof pf._reply_type === 'string' ? pf._reply_type : 'normal',
    _lang_mismatch: typeof pf._lang_mismatch === 'boolean' ? pf._lang_mismatch : null,
    accepted_changes,
    // Top-level flags so UPDATE node can key off them easily
    human_requested,
    human_requested_first_time,
    human_reason,
    human_contact_phone,
    // ==== MINIMAL ADD: downstream visibility of phone update ====
    _phone_updated,
    // ==== NEW: Template rotation & phone ask tracking ====
    _phone_asked_at_qualification: Boolean(
      pf._phone_asked_at_qualification ||
      $json._phone_asked_at_qualification ||
      snap?.rubric_snapshot?._phone_asked_at_qualification
    ),
    _last_template_id: String(
      pf._last_template_id_new ||
      $json._last_template_id_new ||
      pf._last_template_id ||
      $json._last_template_id ||
      snap?.rubric_snapshot?._last_template_id ||
      ''
    )
  }
};

