// Compose Not-Ready (F1) — v10.1.0 (HANDOFF-aware)

function escapeHtml(s) {
  return String(s || '').replace(/[&<>"']/g, c => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": "&#39;" }[c]
  ));
}
function normAddr(a) {
  const s = String(a || '').trim();
  return s.includes(' ') ? s : s.toLowerCase();
}

const c = $json.reply_contract || {};
const subj = c.subject || 'Re: Your enquiry';
// Name is now determined by template based on turn_index, not from LLM
const paras = Array.isArray(c.paragraphs) ? c.paragraphs.filter(Boolean) : [];
const includeSig = (c.include_signature !== false);
const sigText = c.signature_text || 'Kind regards\nAustrump Glen Team';
const logoUrl = c.logo_url || 'https://raw.githubusercontent.com/winstonpgao/arcsage-assets/refs/heads/main/austrumplogo.jpeg';

// HANDOFF flags from upstream
const IS_HANDOFF = $json.human_requested === true || ($json.context_fields && $json.context_fields.human_requested === true);
const IS_FIRST_TIME = $json.human_requested_first_time === true;
const IS_REENGAGED = $json._reengaged_intent === true;

// Phone and turn tracking
const snapNode = $node["Rubric & Load Latest Snapshot"]?.json || {};
const turnIndex = Number(snapNode?.rubric_snapshot?._turn_index || 0);
const hasPhone = Boolean($json._known_phone);

// Language detection
const LANG = $json.reply_contract?.lang || $node["MAIN Build Context"]?.json?.USER_BLOCK?.LANG || 'en';

// Derive client_id and name from upstream (template needs it)
const client_id =
  $json.client_id
  || $node["MAIN Build Context"]?.json?.USER_BLOCK?.SNAPSHOT_JSON?.client_id
  || snapNode?.client_id
  || '';

// Get client display name for template greeting
function pickClientName() {
  const buildCtx = $node["MAIN Build Context"]?.json || {};
  const displayNameReal = buildCtx._display_name_real || '';
  if (displayNameReal) return displayNameReal;

  const snapDisplay = snapNode?.client_display_name || snapNode?.display_name || '';
  if (snapDisplay) return snapDisplay;

  return '';
}
const name = pickClientName();

// If HANDOFF but NOT first time AND NOT reengaged → suppress customer send
if (IS_HANDOFF && !IS_FIRST_TIME && !IS_REENGAGED) {
  return {
    json: {
      subject: subj,
      body: '',
      body_html: '',
      to: normAddr($json.to || ''),
      mailbox: $json.mailbox || 'austrump@arcsage.com.au',
      channel: 'HUMAN_NOTIFY',
      _skip_customer: true,
      _notify_only: true,
      human_requested: true,
      human_requested_first_time: false,
      client_id
    }
  };
}

// Build paragraphs array (start with LLM-generated paragraphs)
let finalParas = [...paras];

// Phone validation state
const phoneValidationState = $json._phone_validation_state || $json.context_fields?.phone_validation_state || null;
const phoneNeedsClarification = $json._phone_needs_clarification === true;
const phoneValidationAttempts = Number($json._phone_validation_attempts || $json.context_fields?.phone_validation_attempts || 0);
const phoneRawInput = $json.context_fields?.phone_raw_input || null;
const phone = $json._known_phone || $json.context_fields?.human_contact_phone || $node["MAIN Build Context"]?.json?.human_contact_phone || null;

// Get client's ORIGINAL message (not the LLM's response) for internal notifications
const buildCtx = $node["MAIN Build Context"]?.json || {};
const clientOriginalMessage = buildCtx.USER_BLOCK?.EMAIL_BODY || buildCtx.customerMail?.message?.body?.content || '';

// Get conversation history for internal notifications
function getConversationHistory() {
  const ub = buildCtx?.USER_BLOCK || {};
  const recentContext = ub.RECENT_CONTEXT || {};
  const last50 = recentContext.last50_in || ub.last50_in || [];

  if (!Array.isArray(last50) || last50.length === 0) {
    return [];
  }

  // Get last 10 messages (both IN and OUT)
  return last50.slice(-10).map(msg => {
    const direction = msg.direction === 'IN' ? 'CLIENT' : 'SYSTEM';
    const text = String(msg.text || msg.body || '').trim().slice(0, 500); // Limit length
    const timestamp = msg.timestamp || msg.date || '';
    return { direction, text, timestamp };
  }).filter(msg => msg.text);
}

// Phone clarification (highest priority)
if (phoneNeedsClarification && phoneValidationState === 'pending_clarification') {
  const clarificationMsg = LANG === 'zh'
    ? `感谢您提供号码"${phoneRawInput || ''}"。能否再次确认格式？澳洲手机号应为04开头的10位数字，例如：0412 345 678。中国手机号应为1开头的11位数字。`
    : `Thanks for providing your number "${phoneRawInput || ''}". Could you please double-check the format? Australian mobile numbers should be 10 digits starting with 04 (e.g., 0412 345 678). Chinese mobile numbers should be 11 digits starting with 1.`;
  finalParas.push(clarificationMsg);
}
// NEW: Handle final failure (incorrect format after retry)
else if (phoneValidationState === 'incorrect_format') {
  const msg = LANG === 'zh'
    ? '抱歉，该号码格式似乎仍不正确。我们会通过邮件与您联系。'
    : 'Sorry, that number still doesn\'t look quite right. We\'ll contact you via email instead.';
  finalParas.push(msg);
}

// FIX #4: Add phone ask at first turn OR when handoff first-time without phone
// Changed from: turnIndex === 0 && !hasPhone
// To: (turnIndex === 0 || (IS_HANDOFF && IS_FIRST_TIME)) && !hasPhone
// ONLY ask if NOT already asking for clarification
else if ((turnIndex === 0 || (IS_HANDOFF && IS_FIRST_TIME)) && !hasPhone && !phoneNeedsClarification) {
  // When handoff, ask phone+time combined; otherwise just phone
  const phoneAsk = (IS_HANDOFF && IS_FIRST_TIME)
    ? (LANG === 'zh'
      ? '为了方便联系，能否提供您的联系电话和最佳通话时间？'
      : 'So they can get in touch, what\'s the best number and time for them to call you?')
    : (LANG === 'zh'
      ? '顺便问一下，能否提供您的联系电话？这样我们可以更及时地与您沟通。'
      : 'By the way, could you please share your contact phone number? This helps us communicate with you more effectively.');
  finalParas.push(phoneAsk);
}

// Add human request acknowledgment if client asked for human AND is reengaging
if (IS_HANDOFF && IS_REENGAGED) {
  const humanAck = LANG === 'zh'
    ? '我们已将您的需求转达给团队，他们会尽快与您联系。同时，我很乐意继续帮您了解更多细节。'
    : 'I\'ve notified our team of your request and they\'ll be in touch soon. In the meantime, I\'m happy to continue helping you with more details.';
  finalParas.push(humanAck);
}

// FIX #1: Determine if we should use client's first name in salutation
// Always use name when available (consistent with Compose Ready Messages)
const USE_FIRST_NAME = Boolean(name && String(name).trim());
const greeting = USE_FIRST_NAME
  ? (LANG === 'zh' ? `Hi ${name},` : `Hi ${name},`)
  : (LANG === 'zh' ? `您好,` : `Hi,`);

// First-time handoff acknowledgement (not reengaging - stop LLM)
let ackText = '';
if (IS_HANDOFF && IS_FIRST_TIME && !IS_REENGAGED) {
  const ackMsg = LANG === 'zh'
    ? '感谢您希望与真人顾问交流，我们已标记您的咨询，团队成员将很快与您联系。'
    : 'Thanks for asking to speak with a person, we have flagged your enquiry and a team member will contact you shortly.';
  ackText = `${greeting}\n\n${ackMsg}\n\nKind regards,\nAustrump Glen Team`;
}

// Normal text body - consistent spacing with Compose Ready Messages
const bodyText = ackText || `${greeting}\n\n${finalParas.join('\n\n')}${includeSig ? '\n\n' + sigText : ''}`.trim();

// HTML body
const NBSP = '&nbsp;';
const spacer = (h) => `<div style="height:${h}px;line-height:${h}px;font-size:${h}px;mso-line-height-rule:exactly;">${NBSP}</div>`;
const twoLines = spacer(10) + spacer(10);
const disclaimerBlock = `<p style="font-size:11px;color:#666;margin-top:12px;">Austrump Glen virtual assistant, operated by Arcsage Technology Pty Ltd.<br>General information only and may contain errors. Privacy and AI notice: <a href="https://privacy.arcsage.com.au" style="color:#666;">https://privacy.arcsage.com.au</a>.</p>`;

// FIX #1: Apply same name usage logic to HTML greeting
const htmlGreeting = USE_FIRST_NAME
  ? `Hi ${escapeHtml(name)},`
  : (LANG === 'zh' ? `您好,` : `Hi,`);

let html;
if (IS_HANDOFF && IS_FIRST_TIME && !IS_REENGAGED) {
  const ackMsg = LANG === 'zh'
    ? '感谢您希望与真人顾问交流，我们已标记您的咨询，团队成员将很快与您联系。'
    : 'Thanks for asking to speak with a person, we have flagged your enquiry and a team member will contact you shortly.';
  html =
    `<p style="margin:0 0 12px 0;">${htmlGreeting}</p>` + twoLines +
    `<p style="margin:0 0 12px 0;">${escapeHtml(ackMsg)}</p>` +
    twoLines +
    `<p style="margin:0;">Kind regards,<br>Austrump Glen Team</p>` +
    twoLines +
    `<div style="margin-top:12px;"><img src="${escapeHtml(logoUrl)}" alt="Austrump Glen" width="140" style="width:140px;max-width:140px;height:auto;display:block;border:0;outline:none;text-decoration:none;"></div>` +
    disclaimerBlock + twoLines + twoLines;
} else {
  html = `<p style="margin:0 0 12px 0;">${htmlGreeting}</p>${twoLines}`;
  for (const p of finalParas) {
    html += `<p style="margin:0 0 12px 0;">${escapeHtml(p)}</p>`;
  }
  if (includeSig) {
    html += `${twoLines}<p style="margin:0;">Kind regards,<br>Austrump Glen Team</p>${twoLines}`;
    html += `<div style="margin-top:12px;"><img src="${escapeHtml(logoUrl)}" alt="Austrump Glen" width="140" style="width:140px;max-width:140px;height:auto;display:block;border:0;outline:none;text-decoration:none;"></div>`;
    html += disclaimerBlock + `${twoLines}${twoLines}`;
  }
}

// Internal notification email
const internalSubject = IS_HANDOFF
  ? `[Action Required] Human Contact Requested - ${name || 'Unknown'}`
  : `[Update] Not Yet Qualified - ${name || 'Unknown'}`;

// Helper to format rows as aligned text table (plain text) - COPIED FROM READY MESSAGES FOR CONSISTENCY
function formatRowsForText(rows) {
  if (!rows.length) return ['(none)'];
  const labels = rows.map(([f]) => f);
  const maxLen = Math.max(...labels.map(l => l.length));
  const out = [];
  for (const [f, vRaw] of rows) {
    const v = String(vRaw || '').trim() || 'Not provided';
    const pad = ' '.repeat(maxLen - f.length + 2);
    out.push(`${f}:${pad}${v}`);
  }
  return out;
}

// HTML table for internal email - COPIED FROM READY MESSAGES FOR CONSISTENCY
function rowsToHtmlTable(title, rows) {
  let html = `<table style="border-collapse:collapse;margin:8px 0;font-size:13px;">`;
  if (title) {
    html += `<tr><th colspan="2" style="text-align:left;padding:6px 10px;border:1px solid #ccc;background:#f5f5f5;">${escapeHtml(title)}</th></tr>`;
  }
  if (!rows.length) {
    html += `<tr><td colspan="2" style="padding:6px 10px;border:1px solid #ccc;">(none)</td></tr>`;
  } else {
    for (const [f, vRaw] of rows) {
      const v = String(vRaw || '').trim() || 'Not provided';
      html += `<tr>
        <td style="padding:4px 10px;border:1px solid #ccc;vertical-align:top;white-space:nowrap;">${escapeHtml(f)}</td>
        <td style="padding:4px 10px;border:1px solid #ccc;vertical-align:top;">${escapeHtml(v)}</td>
      </tr>`;
    }
  }
  html += `</table>`;
  return html;
}

// Prepare rubric data for internal notification
const notifyText = $json.notify_text || ''; // This comes from Handoff & Notify Flags, contains rubric text

// Master Spec Phone Status
let phoneStatusText = 'Not provided';
if (phone) {
  if (phoneValidationState === 'validated') {
    phoneStatusText = `${phone} (Confirmed)`;
  } else if (phoneValidationState === 'incorrect_format') {
    phoneStatusText = 'Invalid (will rely on email)';
  } else {
    phoneStatusText = 'Pending verification';
  }
} else {
  phoneStatusText = 'Pending / not confirmed';
}

// Helper function to format conversation history as HTML
function conversationHistoryToHtml(history) {
  if (!history || history.length === 0) return '';

  let html = '<h3 style="margin-top:16px;margin-bottom:8px;">CONVERSATION HISTORY (Last 10 messages):</h3>';
  html += '<div style="background:#f9f9f9;padding:10px;border:1px solid #ddd;max-height:400px;overflow-y:auto;">';

  history.forEach(msg => {
    const bgColor = msg.direction === 'CLIENT' ? '#e3f2fd' : '#fff3e0';
    html += `<div style="margin-bottom:8px;padding:8px;background:${bgColor};border-left:3px solid ${msg.direction === 'CLIENT' ? '#2196f3' : '#ff9800'};">
      <strong>${msg.direction}:</strong> ${escapeHtml(msg.text)}
    </div>`;
  });

  html += '</div>';
  return html;
}

// Get conversation history
const conversationHistory = getConversationHistory();

// Format conversation history for plain text
function conversationHistoryToText(history) {
  if (!history || history.length === 0) return '';

  let text = '\n\nCONVERSATION HISTORY (Last 10 messages):\n';
  history.forEach(msg => {
    text += `[${msg.direction}]: ${msg.text}\n`;
  });
  return text;
}

const internalBodyText = IS_HANDOFF
  ? `Client ${name || 'Unknown'} (${normAddr($json.to || '')}) has requested to speak with a team member.

Current Status: Not yet qualified
Phone: ${phoneStatusText}

LATEST CLIENT MESSAGE:
${clientOriginalMessage}

${notifyText ? '\nRUBRIC SNAPSHOT & CONTEXT:\n' + notifyText : ''}${conversationHistoryToText(conversationHistory)}

Please contact the client directly.`
  : `Client ${name || 'Unknown'} (${normAddr($json.to || '')}) sent a message but is not yet qualified.

Latest message from client:
${clientOriginalMessage.substring(0, 300)}...

Continue qualifying via email.`;

const internalBodyHtml = IS_HANDOFF
  ? `<p>Client <strong>${escapeHtml(name || 'Unknown')}</strong> (${escapeHtml(normAddr($json.to || ''))}) has requested to speak with a team member.</p>
<p><strong>Current Status:</strong> Not yet qualified<br>
<strong>Phone:</strong> ${escapeHtml(phoneStatusText)}</p>

<h3>LATEST CLIENT MESSAGE:</h3>
<p style="background:#f5f5f5;padding:10px;border-left:3px solid #d32f2f;">${escapeHtml(clientOriginalMessage)}</p>

${notifyText ? '<h3>RUBRIC SNAPSHOT & CONTEXT:</h3><pre style="background:#f9f9f9;padding:10px;border:1px solid #ccc;white-space:pre-wrap;">' + escapeHtml(notifyText) + '</pre>' : ''}

${conversationHistoryToHtml(conversationHistory)}

<p>Please contact the client directly.</p>`
  : `<p>Client <strong>${escapeHtml(name || 'Unknown')}</strong> (${escapeHtml(normAddr($json.to || ''))}) sent a message but is not yet qualified.</p>
<p><strong>Latest message from client:</strong></p>
<p style="background:#f5f5f5;padding:10px;border-left:3px solid #666;">${escapeHtml(clientOriginalMessage.substring(0, 300))}...</p>
<p>Continue qualifying via email.</p>`;

// Only create internalMail when human requested (IS_HANDOFF = true)
// Normal not-qualified messages should NOT notify internal team
const internalMail = IS_HANDOFF ? {
  message: {
    subject: internalSubject,
    body: { contentType: 'HTML', content: internalBodyHtml },
    toRecipients: [{ emailAddress: { address: 'winston@arcsage.com.au' } }],
    attachments: []
  },
  saveToSentItems: true
} : null;

return {
  json: {
    subject: subj,
    body: bodyText,
    body_html: html,
    to: normAddr($json.to || ''),
    mailbox: $json.mailbox || 'austrump@arcsage.com.au',
    channel: IS_HANDOFF ? 'HUMAN_NOTIFY' : 'LLM',
    _skip_customer: IS_HANDOFF ? false : false,
    _notify_only: IS_HANDOFF ? false : false,
    human_requested: IS_HANDOFF || undefined,
    human_requested_first_time: IS_HANDOFF ? IS_FIRST_TIME : undefined,
    client_id,
    internalMail  // Will be null for normal not-qualified messages
  }
};

// Prepare Dedupe Param v10.0.2 (minimal change: add simple dedupe for repeated halves)
// Build a single JSON string param with body + provider_message_id (hardened)

function stripHtml(s = '') { 
  return String(s).replace(/<[^>]+>/g, ' '); 
}

function squeeze(s = '') { 
  return String(s).replace(/\s+/g, ' ').trim(); 
}

function cap(s = '', n = 4000) { 
  const t = String(s || ''); 
  return t.length > n ? t.slice(0, n) : t; 
}

function normProvider(id) {
  const raw = String(id || '');
  if (!raw) return '';
  return raw.replace(/[<>]/g, '').trim().toLowerCase();
}

// NEW: Simple deduplication for when text is repeated exactly twice
function dedupeIfRepeated(text) {
  if (!text || text.length < 20) return text;

  const len = text.length;
  const half = Math.floor(len / 2);

  // Check if first half equals second half (with some tolerance for spaces)
