  const locV3 = f['Locations / School Zones']?.value;
  const locV2 = f['Requirements & Suburbs']?.value;
  if (v(locV3) || v(locV2)) parts.push(`Suburbs: ${v(locV3 || locV2)}`);

  if (v(f['Timeline to Buy / Settle']?.value)) parts.push(`Timeline: ${v(f['Timeline to Buy / Settle'].value)}`);

  const briefV3 = f['Property Brief (type / size / features)']?.value;
  const briefV2 = f['Must-haves / Nice-to-haves']?.value || f['Property Type']?.value;
  if (v(briefV3) || v(briefV2)) parts.push(`Type: ${v(briefV3 || briefV2)}`);

  if (v(ctx.household_people_count)) parts.push(`Household: ${v(ctx.household_people_count)} ppl`);
  if (v(ctx.pets_detail) || v(ctx.has_pets)) parts.push(`Pets: ${v(ctx.pets_detail || ctx.has_pets)}`);
  if (v(ctx.employment_note)) parts.push(`Work: ${v(ctx.employment_note)}`);
  if (v(ctx.commute_anchor)) parts.push(`Commute: ${v(ctx.commute_anchor)}`);

  const custom = (ctx.custom && typeof ctx.custom === 'object') ? ctx.custom : {};
  const entries = Object.entries(custom).map(([k,obj]) => {
    const o = obj || {};
    const conf = Number(o.confidence || 0);
    const val = v(o.value);
    return { k, conf, val };
  }).filter(x => x.val);

  entries.sort((a,b)=> b.conf - a.conf);
