function makeCandidates(){
  const candidates = [];
  const cannotAsk = new Set();

  for (const k of RUBRIC_SUBCRITERIA){
    if (!k) continue;
    const M = Number(RUBRIC_MAX[k] || 0);
    const p = ptsOf(k);
    const q = QHIST[k] || { ask_count:0, no_progress_runs:0, suppressed_runs_left:0 };
    if (q.suppressed_runs_left > 0 || (M>0 && p>=M)) cannotAsk.add(k);
  }

  const QUAL_THRESHOLD = Number(60);  // FIX #8: Changed from 70 to 60
  const totalNow = Object.keys(fieldsNow||{}).reduce((t,k)=> t + (fieldsNow[k]?.points||0), 0);
  const allHaveValue = RUBRIC_SUBCRITERIA.length > 0 && RUBRIC_SUBCRITERIA.every(k => hasValue(k));
  const preferWeak = allHaveValue && (totalNow < QUAL_THRESHOLD);

  for (const k of RUBRIC_SUBCRITERIA){
    if (!k) continue;
    const M = Number(RUBRIC_MAX[k] || 0);
    const p = ptsOf(k);
    const q = QHIST[k] || { no_progress_runs:0, suppressed_runs_left:0 };
    if (q.suppressed_runs_left > 0 || (M>0 && p>=M)) continue;

    let expected_gain = Math.max(0, M - p);
    let penalty = (q.no_progress_runs >= 2) ? -(expected_gain * 0.7) : 0;
    let boost = 0;

    if (preferWeak) {
      boost += (p === 0 ? 3 : (p < Math.max(1, Math.round(M/2)) ? 2 : 0));
    } else {
      if (k === 'Timeline to Buy / Settle' && !fieldsNow['Timeline to Buy / Settle']?.value) boost += 2;
      const fs = (fieldsNow['Financing Status']?.value || '').toLowerCase();
      if (k === 'Decision Makers / Alignment' && fs.includes('progress')) boost += 2;
    }
    candidates.push({ key: k, score: expected_gain + boost + penalty, p, M });
  }

  candidates.sort((a,b)=> b.score - a.score);
  return { 
    CANDIDATE_FIELDS: candidates.slice(0,4).map(x=>x.key), 
    CANNOT_ASK: Array.from(cannotAsk) 
  };
}

