function yesNo(v) { if (v === true) return 'yes'; if (v === false) return 'no'; return String(v ?? ''); }
function flattenContext(cf, prefix = '') {
  const out = [];
  if (!cf || typeof cf !== 'object') return out;
  const SKIP_KEYS = new Set([
    'phone_validation_state', 'phone_validation_attempts', 'phone_validation_issue',
    'phone_raw_input', 'human_requested', 'phone_asked', 'human_contact_phone',
