  for (const [k, v] of Object.entries(cf)) {
    if (SKIP_KEYS.has(k) || k.startsWith('_')) continue;
    const key = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === 'object' && !Array.isArray(v)) out.push(...flattenContext(v, key));
    else {
      const val = Array.isArray(v) ? v.join('; ') : yesNo(v);
