const deltas = parsed.progress_delta_map || {};
const rubricJson = (UB && Array.isArray(UB.RUBRIC_JSON)) ? UB.RUBRIC_JSON : [];
const MAX_MAP = Object.fromEntries(rubricJson.map(r => [String((r.key || r.sub_criterion) || ''), Number((r.max_points ?? r.points) || 0)]));
const DIM_MAP = Object.fromEntries(rubricJson.map(r => [String((r.key || r.sub_criterion) || ''), String(r.dimension || '')]));

const rr = [];
rr.push(`Client: ${UB.client_display_name || snapRow.display_name || 'unknown'} <${$json.to || getMsg.from?.emailAddress?.address || 'unknown'}>`);
rr.push(`Phone: ${phone || '—'}`);
rr.push(`Total score: ${score}/100`);
rr.push('');
rr.push('Rubric');
for (const k of Object.keys(fields)) {
  const r = fields[k] || {};
  const val = String(r.value ?? '').replace(/\s+/g, ' ').trim();
  const dim = DIM_MAP[k] || '';
  const pts = Number(r.points ?? 0);
  const mx = Number(MAX_MAP[k] ?? 0);
  const dlt = Number(deltas[k] ?? 0);
  const evidence = val || r.evidence || '';
  const conf = (typeof r.confidence === 'number') ? r.confidence : '';
  rr.push(`section=rubric field=${k} dimension=${dim} value=${val || ''} classification=${r.classification || ''} points=${pts} max_points=${mx} delta=${dlt} evidence=${String(evidence).replace(/\s+/g, ' ').trim()} confidence=${conf}`);
}
rr.push('');
rr.push('Context');
const ctxOut = flattenContext(parsed.context_fields || snap.context_fields || {});
for (const [k, v] of ctxOut) rr.push(`${k} ${v}`);
const notifyText = rr.join('\n');

// ---------- dynamic subject line generation ----------
function buildNotificationSubject() {
  const clientName = UB.client_display_name || snapRow.display_name || build.display_name || 'Unknown';
  const phoneUpdated = Boolean(parsed._phone_updated);
  const phoneNum = phone || '';

  if (phoneUpdated && phoneNum) {
    return `[Update] Phone Number Provided - ${clientName}: ${phoneNum}`;
  }

  if (wantsHumanCurrent && !alreadyQualified) {
    return `[Action Required] Human Contact Requested - Not Qualified Yet`;
  }

  if (wantsHumanCurrent && alreadyQualified) {
    return `[Urgent] Qualified Lead Requests Human Contact`;
  }

  if (justQualified) {
    return phoneNum
      ? `[New Lead] Client Qualified - Phone: ${phoneNum}`
      : `[New Lead] Client Qualified - Phone Missing`;
  }

  if (alreadyQualified && !justQualified) {
    return `[Update] Qualified Lead Responded - ${clientName}`;
  }

  return `[Update] Lead Activity - ${clientName}`;
}

const notificationSubject = buildNotificationSubject();

// ---------- notify decision (updated) ----------
// Default reason
let notifyReason = 'none';

// Pass → always notify-only, durable handoff
let notifyOnly = false;
if (alreadyQualified) {
  notifyOnly = true;
  notifyReason = 'qualified_pass';
} else if (wantsHumanCurrent) {
  // FIX: If client wants human, we MUST notify internal team.
  // We set notifyOnly=true so the standard LLM flow doesn't try to "qualify" them further in a loop.
  // The Compose Not-Ready node will handle the actual email generation (acknowledgement + internal notify).
  notifyOnly = true;
  notifyReason = 'human_request_current';
} else if (durableHuman && !reengaged) {
  notifyOnly = true;
  notifyReason = 'human_request_durable';
}

// Outputs
return {
  json: {
    ...$json,
    _wants_human: wantsHumanCurrent,
    _reengaged_intent: reengaged,
    _qualified_pass: alreadyQualified,
    _notify_only: notifyOnly,
    _notify_reason: notifyReason,
    _need_phone_now: needPhoneNow,
    _known_phone: phone || '',
    _phone_asked_at_qualification: (needPhoneNow && justQualified) || phoneAskedAtQualification,
    notification_subject: notificationSubject,
    // persistible hints
    human_requested: human_requested_next,
    context_fields: {
      ...(parsed.context_fields || {}),
      human_requested: human_requested_next,
      phone_asked: needPhoneNow === true ? true : (parsed.context_fields?.phone_asked ?? false)
    },
    notify_text: notifyText
  }
};

