-- Recent Same-Body? (20m) v10.0.2
WITH i AS (
  SELECT (
    $$ {{ 
      (function () {
        try {
          const it = $('Prepare Dedupe Param').item($itemIndex);
          if (it && it.json && it.json.dedupe_param) return it.json.dedupe_param;
          const f = $('Prepare Dedupe Param').first();
          if (f && f.json && f.json.dedupe_param) return f.json.dedupe_param;
        } catch (e) {}
        // NEVER return undefined
        return '{}';
      })() 
    }} $$
  )::jsonb AS j
),
now_body AS (
  SELECT
    -- Body from JS is already stripped and squeezed; just trim, cap, lower
    LOWER(
      LEFT(
        BTRIM(COALESCE(i.j->>'body', '')),
        4000
      )
    ) AS body_norm,
    NULLIF(
      LOWER(REGEXP_REPLACE(COALESCE(i.j->>'provider',''), '[<>]', '', 'g')),
      ''
    ) AS pid
  FROM i
)
SELECT EXISTS (
  SELECT 1
  FROM lc.fact_enquiry fe
  CROSS JOIN now_body nb
  WHERE fe.direction = 'IN'
    AND fe.received_at >= now() - interval '20 minutes'
    AND LENGTH(nb.body_norm) > 10
    -- Provider-ID guard: skip exact same provider id if we have it; otherwise fall back to body match
    AND (
      nb.pid IS NULL
      OR NULLIF(
           LOWER(REGEXP_REPLACE(COALESCE(fe.provider_message_id,''), '[<>]', '', 'g')),
           ''
         ) IS DISTINCT FROM nb.pid
    )
    -- Normalised body equality: strip HTML, squeeze spaces, trim, cap to 4000, lower
    AND LOWER(
          LEFT(
            BTRIM(
              REGEXP_REPLACE(
                REGEXP_REPLACE(
                  COALESCE(fe.body_html, fe.body_plain, fe.subject, ''),
                  '<[^>]+>', ' ', 'g'
                ),
                '\s+', ' ', 'g'
              )
            ),
            4000
          )
        ) = nb.body_norm
) AS same_body_recently;

parameters.jsCode:
// Graph Health Monitor — Check subscription health and detect potential gaps
// Runs every 10-15 minutes to monitor Microsoft Graph subscription status

function toStr(x) {
  const s = (x ?? '').toString();
  return /^(undefined|null)$/i.test(s.trim()) ? '' : s;
}

// Get database result: subscription info from lc.graph_subscriptions
const dbResult = $input.all();
const subscription = dbResult[0]?.json || {};

const subscriptionId = toStr(subscription.subscription_id);
const mailbox = toStr(subscription.mailbox) || 'austrump@arcsage.com.au';
const expirationDatetime = subscription.expiration_datetime || null;
const status = toStr(subscription.status) || 'unknown';
const lastRefreshed = subscription.last_refreshed_at || null;

// Current time
const now = new Date();
const nowIso = now.toISOString();

// Check expiration status
let expiresInMinutes = null;
let needsRefresh = false;
let isExpired = false;
let healthStatus = 'healthy';
let action = 'monitor';

if (expirationDatetime) {
  const expiryTime = new Date(expirationDatetime);
  const diffMs = expiryTime - now;
  expiresInMinutes = Math.floor(diffMs / 1000 / 60);

  // If expires in less than 60 minutes: needs refresh
  if (expiresInMinutes < 60) {
    needsRefresh = true;
    healthStatus = 'expiring_soon';
    action = 'refresh_subscription';
  }

  // If already expired: critical
  if (expiresInMinutes < 0) {
    isExpired = true;
    healthStatus = 'expired';
    action = 'resubscribe_and_catchup';
  }
}

// Check for subscription failures (status = 'failed' or 'inactive')
if (status === 'failed' || status === 'inactive') {
  healthStatus = 'failed';
  action = 'resubscribe_and_catchup';
}

// Check for stale last_refreshed (not refreshed in 3+ days despite being active)
if (lastRefreshed && status === 'active' && expiresInMinutes !== null && expiresInMinutes > 60) {
  const lastRefreshTime = new Date(lastRefreshed);
  const daysSinceRefresh = Math.floor((now - lastRefreshTime) / 1000 / 60 / 60 / 24);

  if (daysSinceRefresh > 3) {
    healthStatus = 'stale';
    action = 'refresh_subscription';
  }
}

// Build Graph API subscription refresh URL
const subscriptionRefreshUrl = subscriptionId
  ? `https://graph.microsoft.com/v1.0/subscriptions/${subscriptionId}`
  : null;

// Build Graph API new subscription URL (if resubscribe needed)
const subscriptionCreateUrl = `https://graph.microsoft.com/v1.0/subscriptions`;

// Output structure
const out = {
  // Status flags
  check_at: nowIso,
  subscription_id: subscriptionId,
  mailbox: mailbox,
  status: status,
  health_status: healthStatus,
  action: action,

  // Expiration details
  expiration_datetime: expirationDatetime,
  expires_in_minutes: expiresInMinutes,
  is_expired: isExpired,
  needs_refresh: needsRefresh,

  // Refresh details
  last_refreshed_at: lastRefreshed,

  // API URLs
  refresh_url: subscriptionRefreshUrl,
  create_url: subscriptionCreateUrl,

  // Thresholds
  refresh_threshold_minutes: 60,
  stale_threshold_days: 3,

  // Metadata
  check_type: 'periodic',
  workflow_name: 'Graph Health Monitor',

  // Status message (BUG FIX: Handle null expiresInMinutes)
  status_message:
    action === 'resubscribe_and_catchup' ? `CRITICAL: Subscription ${isExpired ? 'expired' : 'failed'}. Resubscribe and catch up on missed messages.` :
    action === 'refresh_subscription' ? `WARNING: Subscription ${healthStatus === 'stale' ? 'stale' : `expires in ${expiresInMinutes} minutes`}. Refresh needed.` :
    expiresInMinutes !== null ? `OK: Subscription healthy. Expires in ${expiresInMinutes} minutes.` :
    'WARNING: No subscription expiration data available.'
};

// Determine next action routing
out._route = action; // Used by Switch node to route to appropriate action

// Return the result
return {
  json: out,
};

// Graph Startup Catchup — Detect message gaps and prepare delta query
// Runs on n8n workflow startup to catch up on any missed messages

function toStr(x) {
  const s = (x ?? '').toString();
  return /^(undefined|null)$/i.test(s.trim()) ? '' : s;
}

// Get database result: last processed message timestamp
const dbResult = $input.all();
const lastMessageTime = dbResult[0]?.json?.last_message_time || null;

// Current time
const now = new Date();
const nowIso = now.toISOString();

// Calculate time since last message (in minutes)
let minutesSince = null;
let gapDetected = false;
let catchupNeeded = false;
let deltaUrl = null;

if (lastMessageTime) {
  const lastTime = new Date(lastMessageTime);
  const diffMs = now - lastTime;
  minutesSince = Math.floor(diffMs / 1000 / 60);

  // Gap detected if more than 2 hours (120 minutes) since last message
  // This indicates possible subscription failure or missed webhook
  if (minutesSince > 120) {
    gapDetected = true;
    catchupNeeded = true;

    // Build Microsoft Graph API delta query URL
    // This will fetch all messages received since lastMessageTime
    const mailbox = 'austrump@arcsage.com.au';
    const folderId = 'inbox'; // or specific folder ID if needed

    // Format: /users/{mailbox}/mailFolders/{folderId}/messages/delta?$filter=receivedDateTime ge {lastTime}
    // Note: Graph API delta doesn't directly support $filter, so we'll use $deltaLink if available
    // For initial catch-up, we use messages endpoint with filter

    const filterTime = lastTime.toISOString();
    deltaUrl = `https://graph.microsoft.com/v1.0/users/${mailbox}/mailFolders/${folderId}/messages?$filter=receivedDateTime ge ${filterTime}&$orderby=receivedDateTime asc&$top=50`;
  }
}

// Output structure
const out = {
  // Status flags
  startup_check_at: nowIso,
  last_message_time: lastMessageTime,
  minutes_since_last: minutesSince,
  gap_detected: gapDetected,
  catchup_needed: catchupNeeded,

  // Graph API query details
  delta_url: deltaUrl,
  mailbox: 'austrump@arcsage.com.au',
  folder_id: 'inbox',

  // Thresholds
  gap_threshold_minutes: 120,

  // Metadata
  check_type: 'startup',
  workflow_name: 'Graph Startup Catchup',

  // Message for logging
  status_message: catchupNeeded
    ? `GAP DETECTED: ${minutesSince} minutes since last message. Catch-up required.`
    : minutesSince !== null
    ? `No gap detected. Last message was ${minutesSince} minutes ago.`
    : `No previous messages found. This may be first run.`
};

// Return the result
return {
  json: out,
};

// Graph Catchup Process — Format messages from Graph API for database insertion
// Deduplication will be handled by database constraint on provider_message_id

function toStr(x) {
  const s = (x ?? '').toString();
  return /^(undefined|null)$/i.test(s.trim()) ? '' : s;
}

// Get all messages from Graph API catch-up query
const messages = $input.all();

// Process each message
const processed = [];

for (const item of messages) {
  const msg = item.json;

  // Extract message ID (provider_message_id or internetMessageId)
  const messageId = toStr(msg.id || msg.internetMessageId).trim();
  const subject = toStr(msg.subject);
  const receivedDateTime = toStr(msg.receivedDateTime);
  const bodyPreview = toStr(msg.bodyPreview);
  const bodyContent = msg.body?.content || '';
  const bodyContentType = msg.body?.contentType || 'text';

  // Extract sender email
  const senderEmail = msg.from?.emailAddress?.address || '';
  const senderName = msg.from?.emailAddress?.name || '';

  // Skip if no message ID
  if (!messageId) continue;

  processed.push({
    provider_message_id: messageId,
    subject: subject,
    received_at: receivedDateTime,
    body_preview: bodyPreview.slice(0, 500), // Limit preview length
    body_content: bodyContent,
    body_content_type: bodyContentType,
    sender_email: senderEmail.toLowerCase().trim(),
    sender_name: senderName,
    direction: 'IN', // All catch-up messages are inbound
    is_catchup: true, // Flag to indicate this was caught up
    catchup_timestamp: new Date().toISOString()
  });
}

// Summary output
const summary = {
  total_fetched: messages.length,
  messages_to_insert: processed.length,
  processed_messages: processed,
  catchup_completed_at: new Date().toISOString(),
  status: processed.length > 0 ? 'messages_ready_for_insert' : 'no_messages_to_insert',

  // For logging
  mailbox: 'austrump@arcsage.com.au',
  catchup_started_at: new Date().toISOString()
};

// Return summary and processed messages
// Note: Actual deduplication happens in database INSERT with ON CONFLICT DO NOTHING
return {
  json: summary,
};

// Compose F2 — Resend the last LLM reply message WITH unsubscribe links
// v2.0: Added unsubscribe/subscribe links like F1

function toStr(x) {
  const s = (x ?? '').toString();
  return /^(undefined|null)$/i.test(s.trim()) ? '' : s;
}

function escapeHtml(s) {
  return toStr(s).replace(/[&<>"']/g, function (c) {
    const map = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#39;',
    };
    return map[c] || c;
  });
}

// Get data from F2 Detection Query
const client_id = toStr($json.client_id).trim();
const email = toStr($json.email).trim().toLowerCase();
const given_name = toStr($json.given_name);
const family_name = toStr($json.family_name);
const display_name = toStr($json.display_name);

// Last message content (what we're resending)
const last_subject = toStr($json.last_subject);
const last_body_plain = toStr($json.last_body_plain);
const last_body_html = toStr($json.last_body_html);
const last_message_id = toStr($json.last_message_id);

// Validation
if (!client_id) {
  throw new Error('Missing client_id');
}
if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error(`Invalid email: ${email}`);
}
if (!last_body_html && !last_body_plain) {
  throw new Error('No message content to resend');
}

// Generate unsubscribe/subscribe URLs (same as F1, but src=F2)
const base = 'https://n8n.arcsage.com.au/webhook/toggle-sub-v3';
const unsubUrl = `${base}?a=unsub&e=${encodeURIComponent(email)}&t=${encodeURIComponent(client_id)}&src=F2`;
const resubUrl = `${base}?a=resub&e=${encodeURIComponent(email)}&t=${encodeURIComponent(client_id)}&src=F2`;

// PLAIN TEXT: Append unsubscribe links to plain text body
const plainLinks = `\n\n\n` +
  `Stop these emails: ${unsubUrl}\n` +
  `Subscribe again (if you unsubscribed): ${resubUrl}`;

const body_plain_with_links = (last_body_plain || last_body_html.replace(/<[^>]+>/g, ' ').trim()) + plainLinks;

// HTML: Append unsubscribe links to HTML body
const htmlLinks = `
<div style="margin-top:30px;padding-top:20px;border-top:1px solid #e0e0e0;font-size:12px;color:#666;">
  <p style="margin:0;">
    Stop these emails: <a href="${unsubUrl}">Unsubscribe</a><br>
    Changed your mind? <a href="${resubUrl}">Subscribe again</a>
  </p>
</div>
`;

const body_html_with_links = (last_body_html || `<p>${escapeHtml(last_body_plain)}</p>`) + htmlLinks;

// Build output for Send F2 (Graph) node
const out = {
  template: 'F2_RESEND',
  mailbox: 'austrump@arcsage.com.au',
  to: email,
  subject: last_subject || 'Following up on your enquiry',
  body: body_plain_with_links,
  body_html: body_html_with_links,
  client_id: client_id,
  original_message_id: last_message_id,
  skip_send: false,
  given_name,
  family_name,
  display_name,
  unsubUrl,
  resubUrl
};

return out;

