const cfg = $items("F2 Follow-up Config", 0, 0)[0]?.json || {};
const dailyCap  = Number(cfg.daily_cap ?? 10);
const sentToday = Number($items("Get Today F2 Count", 0, 0)[0]?.json?.sent_today ?? 0);

const remaining = Math.max(0, dailyCap - sentToday);
const inItems = $input.all();

// Limit to remaining capacity
const out = inItems.slice(0, remaining).map((it, i) => ({
  json: { ...it.json, _f2_queue_pos: i }
}));

return out;

// Get Message (Unreplied) — Format unreplied message like Graph webhook
// This node simulates what "Get Message (Graph)" returns

const client_id = $json.client_id;
const message_id = $json.message_id;
const subject = $json.subject || 'Your enquiry';
const body_plain = $json.body_plain || '';
const body_html = $json.body_html || body_plain;
const provider_message_id = $json.provider_message_id || message_id;
const from_address = $json.from_address || $json.email;

// Format like Microsoft Graph API message
const graphMessage = {
  id: message_id,
  subject: subject,
  from: {
    emailAddress: {
      address: from_address
    }
  },
  toRecipients: [
    {
      emailAddress: {
        address: 'austrump@arcsage.com.au'
      }
    }
  ],
  body: {
    contentType: body_html ? 'html' : 'text',
    content: body_html || body_plain
  },
  bodyPreview: body_plain ? body_plain.substring(0, 255) : '',
  bodyText: body_plain,
  bodyHtml: body_html,
  internetMessageId: provider_message_id,
  // Add client_id for later reference
  _client_id: client_id,
  _source: 'unreplied_safety_net'
};

return graphMessage;
